<script lang="ts">
  import { page } from '$app/state';
  import { useDemo } from '#lib/demo.svelte';
  import { difficulties, environments, materials, needs, projects } from '#lib/data';
  import type { Material, Need, Project } from '#lib/types';
  import ProjectCard from '#lib/components/ProjectCard.svelte';
  const demo = useDemo();
  let surface = $state(''); let environment = $state(''); let difficulty = $state(''); let hours = $state(''); let sort = $state('popular'); let need = $state(''); let mobile = $state(false); let limit = $state(6);
  $effect(() => { need = page.url.searchParams.get('need') ?? ''; surface = page.url.searchParams.get('material') ?? ''; });
  const filtered = $derived(projects.filter((p) => (!surface || p.material === surface) && (!environment || p.environment === environment) && (!difficulty || p.difficulty === difficulty) && (!hours || p.hours <= Number(hours)) && (!need || p.need === need)).toSorted((a,b) => sort === 'time' ? a.hours - b.hours : sort === 'name' ? a.title[demo.state.language].localeCompare(b.title[demo.state.language]) : 0));
  function clear() { surface = ''; environment = ''; difficulty = ''; hours = ''; need = ''; limit = 6; }
</script>
<section class="section cream"><div class="container"><div class="breadcrumb"><a href="/">{demo.t('Inicio', 'Home')}</a> / {demo.t('Proyectos', 'Projects')}</div><h1>{demo.t('Proyectos', 'Projects')}</h1><p class="intro">{demo.t('Elige lo que quieres hacer. Te acompañamos en cada fase, desde la idea hasta tu kit.', 'Choose what you want to do. We guide you through each phase, from the idea to your kit.')}</p><div class="tabs"><button class:selected={!need} onclick={() => need = ''}>{demo.t('Todos', 'All')}</button>{#each Object.keys(needs) as n}<button class:selected={need === n} onclick={() => need = n}>{needs[n as Need][demo.state.language]}</button>{/each}</div></div></section>
<section class="section"><div class="container filter-layout"><aside><button class="filters-mobile secondary" aria-expanded={mobile} onclick={() => mobile = !mobile}>{demo.t('Filtrar', 'Filter')} ({[surface,environment,difficulty,hours,need].filter(Boolean).length})</button><div class="filters" class:visible={mobile}><div class="row between"><h3>{demo.t('Filtrar', 'Filter')}</h3><button class="text-button" onclick={clear}>{demo.t('Borrar todo', 'Clear all')}</button></div><fieldset><legend>{demo.t('Superficie', 'Surface')}</legend>{#each Object.keys(materials) as m}<label class="check"><input type="radio" name="surface" value={m} bind:group={surface}/>{materials[m as Material][demo.state.language]}</label>{/each}</fieldset><fieldset><legend>{demo.t('Interior o exterior', 'Indoor or outdoor')}</legend>{#each Object.keys(environments) as e}<label class="check"><input type="radio" name="environment" value={e} bind:group={environment}/>{environments[e as keyof typeof environments][demo.state.language]}</label>{/each}</fieldset><fieldset><legend>{demo.t('Dificultad', 'Difficulty')}</legend>{#each Object.keys(difficulties) as d}<label class="check"><input type="radio" name="difficulty" value={d} bind:group={difficulty}/>{difficulties[d as Project['difficulty']][demo.state.language]}</label>{/each}</fieldset><label>{demo.t('Tiempo de muestra disponible', 'Available sample time')}<select bind:value={hours}><option value="">{demo.t('Cualquiera', 'Any')}</option><option value="1">≤ 1 h</option><option value="3">≤ 3 h</option><option value="8">≤ 8 h</option><option value="12">≤ 12 h</option></select></label></div></aside><div><div class="row between"><p class="muted">{filtered.length} {demo.t('proyectos de muestra', 'sample projects')}</p><label>{demo.t('Ordenar', 'Sort')}<select bind:value={sort}><option value="popular">{demo.t('Destacados demo', 'Demo featured')}</option><option value="time">{demo.t('Menor tiempo', 'Shortest time')}</option><option value="name">A → Z</option></select></label></div><div class="tabs">{#each [surface,environment,difficulty,hours,need].filter(Boolean) as tag}<button onclick={() => { if(surface === tag) surface=''; if(environment === tag) environment=''; if(difficulty === tag) difficulty=''; if(hours === tag) hours=''; if(need === tag) need=''; }}>{tag} ×</button>{/each}</div><div class="callout row between"><div><h3>{demo.t('¿No sabes por dónde empezar?', 'Not sure where to start?')}</h3><p class="muted">{demo.t('Cuatro preguntas. Un proyecto para ti.', 'Four questions. A project for you.')}</p></div><a class="button" href="/como-se-hace">{demo.t('Buscador guiado', 'Guided finder')}</a></div><div class="grid cols-3">{#each filtered.slice(0,limit) as p}<ProjectCard project={p}/>{:else}<div class="empty"><p>{demo.t('No hay proyectos con estos filtros.', 'No projects match these filters.')}</p><button onclick={clear}>{demo.t('Borrar filtros', 'Clear filters')}</button></div>{/each}</div>{#if limit < filtered.length}<button class="secondary" style="margin-top:25px" onclick={() => limit += 6}>{demo.t('Cargar más proyectos', 'Load more projects')}</button>{/if}</div></div></section>
